-- AssembleMakeHumanBodies (generated by build_makehuman_rig.py): run once in Studio's command bar.
-- 1. Import each NC_Body_<Gender>_<Build>.fbx with the 3D Importer (Rig type: R15, keep the default scale).
-- 2. Make sure NCBodyData is in ReplicatedStorage.
-- 3. Select ALL the imported body models, paste this into the command bar, press Enter.
-- Each body gets: Humanoid settings, the root part, the attachments tools, hats and Character Studio use, the
-- NC_Body tags, and is filed as ServerStorage.NC_Bodies.<Gender>_<Build>. NCBodyService swaps players into the
-- right one. The default body (Male_Average) is also copied to StarterPlayer.StarterCharacter.
local RS = game:GetService("ReplicatedStorage")
local SS = game:GetService("ServerStorage")
local D = require(RS:WaitForChild("NCBodyData"))
local folder = SS:FindFirstChild("NC_Bodies") or Instance.new("Folder")
folder.Name = "NC_Bodies"
folder.Parent = SS
local need = { "HumanoidRootPart", "LowerTorso", "UpperTorso", "Head", "LeftUpperArm", "LeftLowerArm", "LeftHand",
	"RightUpperArm", "RightLowerArm", "RightHand", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot" }
local done = 0
for _, model in game:GetService("Selection"):Get() do
	if not model:IsA("Model") then
		continue
	end
	local id
	for key in D.bodies do
		if string.find(model.Name, key, 1, true) then
			id = key
		end
	end
	if not id then
		warn("AssembleMakeHumanBodies: can't tell which body " .. model.Name .. " is (keep NC_Body_<Gender>_<Build> in its name)")
		continue
	end
	local B = D.bodies[id]
	for _, n in need do
		if not model:FindFirstChild(n, true) then
			warn(id .. ": missing " .. n .. " (import with Rig type R15)")
		end
	end
	local hrp = model:FindFirstChild("HumanoidRootPart")
	if not hrp then
		warn(id .. ": no HumanoidRootPart, skipped")
		continue
	end
	hrp.Size, hrp.Transparency, hrp.CanCollide = Vector3.new(2, 2, 1), 1, true
	model.PrimaryPart = hrp
	local hum = model:FindFirstChildOfClass("Humanoid") or Instance.new("Humanoid")
	hum.Parent = model
	hum.RigType = Enum.HumanoidRigType.R15
	pcall(function() hum.AutomaticScalingEnabled = false end)
	hum.HipHeight = B.hipHeight
	local origin = hrp.CFrame * CFrame.new(0, -B.hrpY, 0)
	for _, a in B.attachments do
		local part = model:FindFirstChild(a[1])
		if part then
			local at = part:FindFirstChild(a[2]) or Instance.new("Attachment")
			at.Name = a[2]
			at.Parent = part
			at.WorldCFrame = origin * CFrame.new(a[3])
		end
	end
	for _, d in model:GetDescendants() do
		if d:IsA("MeshPart") then
			d.CanCollide = d.Name == "UpperTorso" or d.Name == "LowerTorso" or d.Name == "Head"
			pcall(function() d.CollisionFidelity = Enum.CollisionFidelity.Box end)
			d.Anchored = false
			d.Massless = false
		end
	end
	hrp.Anchored = false
	model:SetAttribute("NC_Body", "Human")
	model:SetAttribute("NC_BodyId", id)
	model.Name = id
	local old = folder:FindFirstChild(id)
	if old and old ~= model then
		old:Destroy()
	end
	model.Parent = folder
	if id == D.DEFAULT then
		local sp = game:GetService("StarterPlayer")
		local prev = sp:FindFirstChild("StarterCharacter")
		if prev then
			prev:Destroy()
		end
		local c = model:Clone()
		c.Name = "StarterCharacter"
		c.Parent = sp
	end
	done += 1
end
print("AssembleMakeHumanBodies: " .. done .. " bodies ready in ServerStorage.NC_Bodies")
